def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Last-round action: defection is dominant when there is no future.
    if n >= 99:
        return 'D'

    opp_d = 0
    recent5 = 0
    recent10 = 0
    start5 = n - 5
    start10 = n - 10

    for i in range(n):
        mine, opponent = history[i]
        if opponent == 'D':
            opp_d += 1
            if i > start5:
                recent5 += 1
            if i > start10:
                recent10 += 1

    last_mine, last_opponent = history[-1]

    # Strong defector detection: punish hard and do not try to cooperate.
    if opp_d == n:
        return 'D'
    if recent5 >= 4:
        return 'D'
    if opp_d * 4 >= n * 3:
        return 'D'

    # Exploit defect-free partners after a brief cooperation probe.
    if opp_d == 0:
        if n < 10:
            return 'C'
        if n == 10:
            return 'D'
        if n == 11 and last_mine == 'D' and last_opponent == 'C':
            return 'C'
        return 'D'

    # Responsive branch: punish repeated or mixed defection, but forgive
    # isolated lapses by strongly cooperative opponents and break cycles.
    if last_opponent == 'D':
        if recent5 == 1 and recent10 == 1 and opp_d * 4 <= n:
            return 'C'
        if last_mine == 'D' and recent5 <= 2 and opp_d * 2 <= n:
            return 'C'
        return 'D'

    # Opponent just cooperated. If its recent behavior is not clearly mutual
    # cooperation, prefer defection to avoid being exploited by probes.
    if recent5 >= 2:
        return 'D'
    if recent10 >= 2 and opp_d * 3 >= n:
        return 'D'

    return 'C'
